import{GEAR,equipmentItems,validEquipment}from'./expedition-equipment.mjs';
import{HEROES,ATTR,MAX_TRAINING_RANK}from'./expedition-data.mjs';
export const EQUIPMENT_REQUIREMENT_RULE='本项目新装备只检查角色基础属性＋已投入的永久属性训练；战前倾向、所有装备/套装加成与战斗临时效果均不参与。未满足不能购买并穿戴、换装、应用配装或出征；已穿戴时不能退回使条件失效的培养，先换下再重修。已持有物品与保存配装仍保留，不自动脱装或扣钱。具体门槛与规则为项目原创，非原版现服数值。';
// Fast no-op for old gear; saved sets can remain owned but temporarily ineligible.
export function equipmentRequirementRows(member,gear=member?.gear,training=member?.training){const items=equipmentItems(gear);if(!items.some(i=>i?.requirements))return [];const t=HEROES.find(t=>t.id===member?.id);if(!t||!validEquipment(gear))throw Error('装备条件缺少有效角色或三部位');const rows=[];for(const item of items){if(!item.requirements)continue;const q=item.requirements;if(typeof q!=='object'||Array.isArray(q)||!Object.keys(q).length||Object.entries(q).some(([k,n])=>!Object.hasOwn(ATTR,k)||!Number.isSafeInteger(n)||n<1||n>50))throw Error('装备属性条件定义无效');for(const[key,required]of Object.entries(q)){const base=t.attrs[key],value=training?.['attr:'+key],rank=value===undefined?0:value;if(!Number.isSafeInteger(base)||base<0||!Number.isSafeInteger(rank)||rank<0||rank>MAX_TRAINING_RANK)throw Error('装备条件的永久属性来源无效');rows.push({id:Object.keys(GEAR).find(k=>GEAR[k]===item),name:item.name,key,attribute:ATTR[key],base,training:rank,actual:base+rank,required,reachable:base+MAX_TRAINING_RANK>=required,met:base+rank>=required});}}return rows;}
export function equipmentRequirementFailures(member,gear=member?.gear,training=member?.training){return equipmentRequirementRows(member,gear,training).filter(r=>!r.met).map(r=>r.name+'需永久'+r.attribute+r.required+'，当前'+r.actual);}
export function assertEquipmentRequirements(member,gear=member?.gear,training=member?.training){const failures=equipmentRequirementFailures(member,gear,training);if(failures.length)throw Error('装备条件未满足：'+failures.join('；')+'。请先换装或培养对应属性。');}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function equipmentRequirementsView(member,gear=member?.gear,training=member?.training){let rows;try{rows=equipmentRequirementRows(member,gear,training);}catch{return '<p class="equipment-requirements-unverified">装备条件未核实，请核对角色、部位与永久训练；未据此确认可穿戴。</p>';}return rows.length?'<section class="equipment-requirements"><h3>永久属性穿戴条件</h3>'+rows.map(r=>'<p data-gear-requirement="'+esc(r.id)+'" data-met="'+r.met+'">'+esc(r.name)+'：'+esc(r.attribute)+' 基础'+esc(r.base)+'＋培养'+esc(r.training)+'＝'+esc(r.actual)+' / 需要'+esc(r.required)+' · '+(r.met?'已满足':r.reachable?'尚未满足':'当前培养上限也不能达成，请选择其他装备')+'</p>').join('')+'<small>'+esc(EQUIPMENT_REQUIREMENT_RULE)+'</small></section>':'';}
